import{t as e}from"./framework~index~app-page-cache-render~app-page-cache~page~page~page~page~page~page~page~pag~jbnq3mt7-2y7w5f-4.js";var t=e(),n=[[`Objet du service`,`PRONOSTICS 2M est un service d’analyse et de pronostics sportifs proposé par abonnement. Le service consiste à publier des analyses et des sélections. Il ne constitue ni un conseil en investissement, ni une promesse de gain.`],[`Absence de garantie de résultat`,`Les paris sportifs comportent un risque de perte d’argent. Aucun résultat n’est garanti et les performances passées ne préjugent pas des performances futures. L’abonné reste seul responsable des mises qu’il engage.`],[`Accès réservé aux majeurs`,`Le service est strictement réservé aux personnes majeures. En créant un compte, l’utilisateur déclare avoir 18 ans révolus.`],[`Abonnements et paiement`,`Les paiements sont traités par Stripe. Les abonnements mensuels sont reconduits automatiquement jusqu’à résiliation par l’abonné depuis le portail client Stripe. Les formules « à vie » font l’objet d’un paiement unique. L’accès VIP est activé uniquement après confirmation du paiement par Stripe.`],[`Résiliation`,`L’abonné peut arrêter le renouvellement de son abonnement mensuel à tout moment depuis son profil. L’accès reste ouvert jusqu’au terme de la période déjà payée.`],[`Compte et sécurité`,`Chaque compte est personnel. Le partage des identifiants ou la rediffusion des pronostics entraîne la fermeture du compte sans remboursement. Les mots de passe sont stockés sous forme d’empreinte chiffrée et ne sont lisibles par personne.`],[`Données personnelles`,`Les données collectées (pseudo, email, historique d’abonnement) servent exclusivement à la fourniture du service. L’utilisateur peut demander leur suppression via la page contact.`],[`Jeu responsable`,`Jouer comporte des risques : endettement, isolement, dépendance. Joueurs Info Service : 09 74 75 13 13 (appel non surtaxé).`]];function r(){return(0,t.jsx)(`section`,{className:`section`,children:(0,t.jsxs)(`div`,{className:`wrap stack gap-14`,style:{maxWidth:640},children:[(0,t.jsx)(`h1`,{className:`disp page-title`,children:`CONDITIONS GÉNÉRALES`}),(0,t.jsx)(`div`,{className:`stack gap-14`,children:n.map(([e,n])=>(0,t.jsxs)(`div`,{className:`card-flat`,children:[(0,t.jsx)(`b`,{className:`disp`,style:{fontSize:18},children:e.toUpperCase()}),(0,t.jsx)(`p`,{className:`small muted mt-12`,style:{lineHeight:1.65},children:n})]},e))}),(0,t.jsx)(`p`,{className:`xs dim`,children:`Éditeur du site : [RAISON SOCIALE] — [ADRESSE] — [SIRET]. Contact : [VOTRE EMAIL].`})]})})}export{r as default};